package io.resupply.karoo.data

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import timber.log.Timber

/**
 * A downloadable POI region shown in the picker. Mirrors an entry of the bundled
 * `assets/regions.json`, generated by the data pipeline from `tools/poi-db/regions.ts`
 * (`npm run gen:regions-json`), so the two never drift.
 *
 * This carries only what the picker needs offline (label + group). Download details —
 * file, size, sha256 — come from the live manifest ([RegionManifest]) fetched on demand
 * for the region the rider selects.
 */
@Serializable
data class Region(
    val id: String,
    val label: String,
    /** Picker section, e.g. "Europe" or "North America". */
    val group: String,
) {
    companion object {
        /**
         * Whether [installed] (the set of directly-installed region ids) covers [rowId].
         * A region covers itself; installing a whole-country "Complete" (germany / usa /
         * canada) additionally covers every `<country>-<sub>` row, since that download
         * contains them all. Used by the picker to show ✓ on a state/Bundesland once its
         * country is installed.
         *
         * A child id is `<parent>-<sub>`, so the parent id is the prefix before the first
         * `-`. This relies on parent ids being single-token (germany/usa/canada); leaf
         * countries whose own id contains a `-` (bosnia-herzegovina, united-kingdom, …)
         * have no children, and their prefix (e.g. "bosnia") isn't an installed id, so no
         * false coverage results.
         */
        fun covers(installed: Set<String>, rowId: String): Boolean =
            rowId in installed ||
                rowId.substringBefore('-').let { it != rowId && it in installed }
    }
}

/**
 * The live region manifest (a GitHub release asset). Lists every downloadable region
 * with its file + integrity metadata. [schemaVersion] must equal the app's
 * [PoiDatabase.BUNDLED_DB_VERSION]; a mismatch means the app is too old/new for these
 * files and the download must be refused.
 */
@Serializable
data class RegionManifest(
    val schemaVersion: Int,
    /** Absolute URL prefix; a region file lives at `baseUrl + entry.file`. */
    val baseUrl: String,
    val regions: List<RegionManifestEntry>,
) {
    /**
     * The picker's catalog derived straight from the manifest: every entry's id/label/group.
     * This is why adding a region needs no app release — a newly-published manifest entry
     * shows up in the picker as soon as the manifest is fetched (or read from the disk cache).
     * The bundled `regions.json` ([RegionCatalog]) is only the cold-start fallback seed.
     */
    fun toRegions(): List<Region> = regions.map { Region(it.id, it.label, it.group) }
}

@Serializable
data class RegionManifestEntry(
    val id: String,
    val label: String,
    val group: String,
    /** Filename under [RegionManifest.baseUrl], e.g. `germany-hessen-v5.sqlite.gz`. */
    val file: String,
    val bytesGz: Long,
    val bytesRaw: Long,
    val poiCount: Int,
    /** Lowercase hex SHA-256 of the gzipped file, verified after download. */
    val sha256: String,
    /**
     * Monotonic data version of this region file, bumped by the pipeline when it's rebuilt
     * with fresher OSM data. The Regions screen offers an update when this outranks the
     * installed version ([PoiDatabase.installedRegionVersionsFromDb]). Defaults to 1 so a
     * manifest predating the field still parses.
     */
    val dataVersion: Int = 1,
)

/**
 * Reads the bundled region catalog — the **cold-start fallback seed** so the picker renders a
 * non-empty Browse list offline, before any manifest is fetched. Once the fetched (or
 * disk-cached) manifest is available, [RegionManifest.toRegions] supersedes this, so a region
 * added to the manifest appears with no app release.
 */
object RegionCatalog {
    private const val ASSET = "regions.json"
    private val json = Json { ignoreUnknownKeys = true }

    /** Parse `assets/regions.json`; empty list if the asset is missing/unreadable. */
    fun load(context: Context): List<Region> =
        runCatching {
            context.applicationContext.assets.open(ASSET).use { input ->
                json.decodeFromString<List<Region>>(input.readBytes().decodeToString())
            }
        }.onFailure { Timber.e(it, "failed to read $ASSET") }.getOrDefault(emptyList())
}
